  "questions": [
    {
      "stem": "彼は医師としての仕事のかたわら、（　）を続けている。",
      "options": ["音楽の勉強", "音楽を勉強", "音楽勉強", "音楽勉強する"],
      "answer_index": 0,
      "translation_zh": "他在担任医生的工作之余，继续学习音乐。",
      "explanation_zh": "「かたわら」前接名词需加「の」。选项一接续正确；二缺助词；三、四结构不完整或动词形错误。",
      "option_explanations_zh": [
        "名词+の+かたわら，符合语法要求，表示主业与副业并行。",
        "动词原形不能直接接かたわら，此处需名词化形式加助词。",
        "缺少必要的助词「の」，导致名词与后续成分连接不自然。",
        "动词基本形无法直接修饰かたわら，且结构不符合惯用表达。"
      ]
    },
    {
      "stem": "母は家庭を顧みるかたわら、（　）も欠かさず行っている。",
      "options": ["地域の清掃活動", "地域を清掃活動", "地域清掃活動", "地域清掃する"],
      "answer_index": 0,
      "translation_zh": "母亲在照顾家庭的同时，也从未间断地参与社区清洁活动。",
      "explanation_zh": "「かたわら」前接动词连用形或名词+の。选项一为完整名词短语；二、三助词缺失或搭配不当；四动词形错误。",
      "option_explanations_zh": [
        "名词短语直接作主语，与かたわら前的结构形成自然并列关系。",
        "「を」在此处多余，导致前后成分逻辑连接混乱。",
        "缺少助词使名词修饰关系不明，不符合标准书面语习惯。",
        "动词原形不能直接置于此位置，需改为名词性表达才通顺。"
      ]
    }
  ]
}
